import java.util.*;

class Solution {
  public int[] countVisitedNodes(List<Integer> edges) {
    int n = edges.size();
    int[] state = new int[n], answer = new int[n];
    for (int start = 0; start < n; start++)
      if (state[start] == 0) {
        List<Integer> path = new ArrayList<>();
        Map<Integer, Integer> pos = new HashMap<>();
        int u = start;
        while (state[u] == 0) {
          state[u] = 1;
          pos.put(u, path.size());
          path.add(u);
          u = edges.get(u);
        }
        int from = path.size();
        if (state[u] == 1 && pos.containsKey(u)) {
          int cycleStart = pos.get(u), cycleLength = path.size() - cycleStart;
          for (int i = cycleStart; i < path.size(); i++) {
            answer[path.get(i)] = cycleLength;
            state[path.get(i)] = 2;
          }
          from = cycleStart;
        }
        for (int i = from - 1; i >= 0; i--) {
          int v = path.get(i);
          answer[v] = answer[edges.get(v)] + 1;
          state[v] = 2;
        }
      }
    return answer;
  }
}
